<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeTitleVO;

trait ConsentPurposeTitleAccessor
{
    private ConsentPurposeTitleVO $_title;
    public function getTitle(): string
    {
        return $this->_title->value();
    }
    public function title(): ConsentPurposeTitleVO
    {
        return $this->_title;
    }
    public function isTitleChanged(?self $original = null): bool
    {
        return !$this->_title->equals($original?->_title);
    }
    public function withTitle(ConsentPurposeTitleVO|string $title): self
    {
        $copy = clone $this;
        $copy->_title = ConsentPurposeTitleVO::from($title);
        return $copy;
    }
}
